public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        int c = str.charAt(i);
        if (c < 0x80) {
            size++;
        } else if (c < 0xC0) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        } else if (c < 0xE0) {
            size += 2;
        } else if (c < 0xF0) {
            size += 3;
        } else if (c < 0xF8) {
            size += 4;
        } else if (c < 0xFC) {
            size += 5;
        } else if (c < 0xFE) {
            size += 6;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return size;
}
