final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }
    if (charBuffer == null || charBuffer.length < classFileBuffer.length) {
        throw new IllegalArgumentException("Buffer is not large enough");
    }
    int utf8Length = classFileBuffer[constantPoolEntryIndex];
    if (utf8Length == 0) {
        return "";
    }
    if (utf8Length > charBuffer.length) {
        throw new IllegalArgumentException("Buffer is not large enough");
    }
    for (int i = 0; i < utf8Length; i++) {
        charBuffer[i] = (char) classFileBuffer[constantPoolEntryIndex + 1 + i];
    }
    return new String(charBuffer, 0, utf8Length);
}
