private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Create a new list to hold the nodes to be moved
    DoublyLinkedList<E> tempList = new DoublyLinkedList<>();

    // Move all nodes from the input list to the temporary list
    while (!list.isEmpty()) {
        ListNode<E> node = list.removeFirst();
        tempList.addLast(node);
    }

    // Clear the input list
    list.clear();

    // Add all nodes from the temporary list to the input list
    while (!tempList.isEmpty()) {
        ListNode<E> node = tempList.removeFirst();
        list.addLast(node);
    }
}
