    // Implementation of the readTag method
    // This method reads a field tag from the input stream and returns it
    // If the end of the stream is reached, it returns 0
    // The method handles potential IOExceptions
    // Example implementation:
    int tag = 0;
    while (true) {
        int b = inputStream.read();
        if (b == -1) {
            return 0;
        }
        tag = (tag << 8) | b;
        if ((tag & 0x80000000) == 0) {
            return tag;
        }
    }
}
